import React from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, Grid } from '@react-three/drei';
import type {
  Wall,
    Window as WindowType,
      Door,
        Column,
          Stair,
            StairElement,
            } from '../../core/types';
            import { computeBuildingCenter, computeBuildingSize } from '../../core/scene3DHelpers';
            import { splitWallByOpenings } from '../../core/wallSegments3D';
            import { getWallTexture, getTextureRepeatScale } from '../../core/wallTextures';
            import { WallMesh } from './WallMesh';
            import { FloorContent } from './FloorContent';
            import { Slab3D } from './Slab3D';
            import {
              getWallMaterialProps,
                partitionWalls,
                } from './helpers/wallHelpers';
                import type { View3DSettings, WallMaterialType } from './View3DSettingsDialog';

                interface Props {
                  walls: Wall[];
                    windows: WindowType[];
                      doors: Door[];
                        columns: Column[];
                          stairs: Stair[];
                            stairElements: StairElement[];
                              floorHeights: number[];
                                settings: View3DSettings;
                                }

                                export const Scene3D: React.FC<Props> = ({
                                  walls, windows, doors, columns, stairs, stairElements, floorHeights, settings,
                                  }) => {
                                    // ✅ فلترة الخطوط المساعدة وحدود الأرض
                                      const visibleWalls = React.useMemo(
                                          () => walls.filter(w => w.kind !== 'helper-line' && w.kind !== 'land-boundary'),
                                              [walls],
                                                );

                                                  // ✅ فصل السور
                                                    const { fenceWalls, normalWalls } = React.useMemo(
                                                        () => partitionWalls(visibleWalls),
                                                            [visibleWalls],
                                                              );

                                                                // ✅ أعلى دور موجود
                                                                  const maxFloor = React.useMemo(() => {
                                                                      let max = 0;
                                                                          const check = (f?: number) => { const v = f ?? 0; if (v > max) max = v; };
                                                                              visibleWalls.forEach(w => check(w.floor));
                                                                                  windows.forEach(w => check(w.floor));
                                                                                      doors.forEach(d => check(d.floor));
                                                                                          columns.forEach(c => check(c.floor));
                                                                                              stairs.forEach(s => check(s.floor));
                                                                                                  stairElements.forEach(el => check(el.floor));
                                                                                                      return max;
                                                                                                        }, [visibleWalls, windows, doors, columns, stairs, stairElements]);

                                                                                                          // ✅ ثابت سماكة السقف
                                                                                                          const SLAB_THICKNESS = 0.30;

                                                                                                          // ✅ إزاحة Y لكل دور (مع سماكة السقف بين الأدوار)
                                                                                                          const floorBaseY = React.useMemo(() => {
                                                                                                            const arr: number[] = [0];
                                                                                                              for (let f = 1; f <= maxFloor; f++) {
                                                                                                                  arr[f] = arr[f - 1] + (floorHeights[f - 1] ?? settings.floorHeight) + SLAB_THICKNESS;
                                                                                                                    }
                                                                                                                      return arr;
                                                                                                                      }, [maxFloor, floorHeights, settings.floorHeight]);

                                                                                                                      // ✅ الارتفاع الكلي (مع سقف أعلى دور)
                                                                                                                      const totalHeight = React.useMemo(() => {
                                                                                                                        return floorBaseY[maxFloor] + (floorHeights[maxFloor] ?? settings.floorHeight) + SLAB_THICKNESS;
                                                                                                                        }, [floorBaseY, maxFloor, floorHeights, settings.floorHeight]);

                                                                                                                                                const center = computeBuildingCenter(visibleWalls);
                                                                                                                                                  const size = computeBuildingSize(visibleWalls);
                                                                                                                                                    const camDist = Math.max(size * 1.2, 8);

                                                                                                                                                      // ✅ viewHeight للأرضي (للسور)
                                                                                                                                                        const groundFloorHeight = floorHeights[0] ?? settings.floorHeight;
                                                                                                                                                          const groundViewHeight =
                                                                                                                                                              settings.sectionHeight > 0 && settings.sectionHeight < groundFloorHeight
                                                                                                                                                                    ? settings.sectionHeight
                                                                                                                                                                          : groundFloorHeight;

                                                                                                                                                                            const matProps = getWallMaterialProps(settings.wallMaterial, settings.wallColor);
                                                                                                                                                                              const texture = React.useMemo(
                                                                                                                                                                                  () => getWallTexture(settings.wallMaterial),
                                                                                                                                                                                      [settings.wallMaterial],
                                                                                                                                                                                        );
                                                                                                                                                                                          const repeatScale = getTextureRepeatScale();

                                                                                                                                                                                            // ✅ إعدادات السور
                                                                                                                                                                                              const extSettings = settings as View3DSettings & {
                                                                                                                                                                                                  showFence?: boolean;
                                                                                                                                                                                                      fenceHeight?: number;
                                                                                                                                                                                                          fenceMaterial?: WallMaterialType;
                                                                                                                                                                                                              fenceColor?: string;
                                                                                                                                                                                                                };
                                                                                                                                                                                                                  const showFence = extSettings.showFence ?? true;
                                                                                                                                                                                                                    const fenceHeight = extSettings.fenceHeight ?? 2.5;
                                                                                                                                                                                                                      const fenceMaterial = extSettings.fenceMaterial ?? 'plain';
                                                                                                                                                                                                                        const fenceColor = extSettings.fenceColor ?? '#E8E4DC';

                                                                                                                                                                                                                          const fenceMatProps = getWallMaterialProps(fenceMaterial, fenceColor);
                                                                                                                                                                                                                            const fenceTexture = React.useMemo(
                                                                                                                                                                                                                                () => getWallTexture(fenceMaterial),
                                                                                                                                                                                                                                    [fenceMaterial],
                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                        const fenceViewHeight = Math.min(fenceHeight, groundViewHeight);

                                                                                                                                                                                                                                          // ✅ viewHeight لكل دور (تطبيق sectionHeight)
                                                                                                                                                                                                                                            const getViewHeightForFloor = (f: number): number => {
                                                                                                                                                                                                                                                const fh = floorHeights[f] ?? settings.floorHeight;
                                                                                                                                                                                                                                                    return settings.sectionHeight > 0 && settings.sectionHeight < fh
                                                                                                                                                                                                                                                          ? settings.sectionHeight
                                                                                                                                                                                                                                                                : fh;
                                                                                                                                                                                                                                                                  };

                                                                                                                                                                                                                                                                    return (
                                                                                                                                                                                                                                                                        <Canvas
                                                                                                                                                                                                                                                                              camera={{
                                                                                                                                                                                                                                                                                      position: [
                                                                                                                                                                                                                                                                                                center.x + camDist,
                                                                                                                                                                                                                                                                                                          Math.max(size * 1.2, totalHeight * 1.5),
                                                                                                                                                                                                                                                                                                                    center.y + camDist,
                                                                                                                                                                                                                                                                                                                            ],
                                                                                                                                                                                                                                                                                                                                    fov: 50,
                                                                                                                                                                                                                                                                                                                                            near: 0.1,
                                                                                                                                                                                                                                                                                                                                                    far: 500,
                                                                                                                                                                                                                                                                                                                                                          }}
                                                                                                                                                                                                                                                                                                                                                                style={{ width: '100%', height: '100%', background: '#87CEEB' }}
                                                                                                                                                                                                                                                                                                                                                                    >
                                                                                                                                                                                                                                                                                                                                                                          <ambientLight intensity={0.75} />
                                                                                                                                                                                                                                                                                                                                                                                <directionalLight position={[10, 20, 10]} intensity={0.7} />
                                                                                                                                                                                                                                                                                                                                                                                      <directionalLight position={[-10, 15, -10]} intensity={0.3} />

                                                                                                                                                                                                                                                                                                                                                                                            {settings.showFloor && (
                                                                                                                                                                                                                                                                                                                                                                                                    <mesh rotation={[-Math.PI / 2, 0, 0]} position={[center.x, 0, center.y]}>
                                                                                                                                                                                                                                                                                                                                                                                                              <planeGeometry args={[size * 2.5, size * 2.5]} />
                                                                                                                                                                                                                                                                                                                                                                                                                        <meshStandardMaterial color="#e8e8e8" roughness={0.9} />
                                                                                                                                                                                                                                                                                                                                                                                                                                </mesh>
                                                                                                                                                                                                                                                                                                                                                                                                                                      )}

                                                                                                                                                                                                                                                                                                                                                                                                                                            {/* ✅ الأدوار */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                  {Array.from({ length: maxFloor + 1 }).map((_, f) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                          <group key={`floor-${f}`} position={[0, floorBaseY[f], 0]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <FloorContent
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                floorIndex={f}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            normalWalls={normalWalls}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        windows={windows}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    doors={doors}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                columns={columns}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            stairs={stairs}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        stairElements={stairElements}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    floorHeight={floorHeights[f] ?? settings.floorHeight}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                viewHeight={getViewHeightForFloor(f)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            settings={settings}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        matProps={matProps}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    texture={texture}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                repeatScale={repeatScale}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </group>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ))}

                                                                                                                {/* ✅ السقف فوق كل دور (بحدود جدران الدور نفسه — يغطي مساحته كاملة) */}
                                                                                                                {Array.from({ length: maxFloor + 1 }).map((_, f) => {
                                                                                                                  // ✅ جدران الدور الحالي (الذي السقف يمثّل سقفه)
                                                                                                                    const currentFloorWalls = normalWalls.filter(w => (w.floor ?? 0) === f);
                                                                                                                    
                                                                                                                      if (currentFloorWalls.length === 0) return null;
                                                                                                                      
                                                                                                                        const slabY = floorBaseY[f] + (floorHeights[f] ?? settings.floorHeight);
                                                                                                                        
                                                                                                                          return (
                                                                                                                              <Slab3D
                                                                                                                                    key={`slab-${f}`}
                                                                                                                                          walls={currentFloorWalls}
                                                                                                                                                yBottom={slabY}
                                                                                                                                                      thickness={SLAB_THICKNESS}
                                                                                                                                                          />
                                                                                                                                                            );
                                                                                                                                                            })}                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {/* ✅ السور */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {showFence &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            fenceWalls.flatMap((wall) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const boxes = splitWallByOpenings(wall, [], [], fenceHeight, fenceViewHeight);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return boxes.map((box, idx) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <WallMesh
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          key={`fence-${wall.id}-${idx}`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        box={box}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      matProps={fenceMatProps}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    texture={fenceTexture}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  repeatScale={repeatScale}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                isFence
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              })}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {settings.showGrid && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Grid
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      position={[center.x, 0.01, center.y]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                args={[size * 3, size * 3]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          cellSize={1}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cellColor="#bbbbbb"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              sectionSize={5}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        sectionColor="#666666"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  fadeDistance={size * 3}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            infiniteGrid={false}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <OrbitControls
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        target={[center.x, totalHeight / 2, center.y]}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                enablePan
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        enableZoom
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                enableRotate
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        enableDamping
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                dampingFactor={0.1}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        rotateSpeed={0.35}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                zoomSpeed={0.5}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        panSpeed={0.5}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                minDistance={2}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        maxDistance={size * 4 + totalHeight * 2}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                maxPolarAngle={Math.PI / 2}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </Canvas>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };